begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','99980000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Current explanation course','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score)values('10000000-0000-4000-8000-000000000001','99990000-0000-4000-8000-000000000001','99980000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Current explanation','School task',10);
insert into app.submissions(school_id,id,assessment_id,learner_id,content)values('10000000-0000-4000-8000-000000000001','99991000-0000-4000-8000-000000000001','99990000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','Own original explanation');
insert into app.enrollments(school_id,class_id,student_actor_id,effective_from)values('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000013',now()-interval '1 day')on conflict(school_id,class_id,student_actor_id)do update set status='active';
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is(internal.read_own_assessment_submissions(array['99990000-0000-4000-8000-000000000001'::uuid])->0->>'content','Own original explanation','Exact learner-owned current source is available');
select throws_ok($$select internal.read_own_assessment_submissions(array['ffffffff-ffff-4fff-8fff-ffffffffffff'::uuid])$$,'42501',null,'Missing or foreign assessment cannot become an empty own source');
select throws_ok($$select internal.read_own_assessment_submissions(array_fill('99990000-0000-4000-8000-000000000001'::uuid,array[101]))$$,'22023',null,'Unbounded source inputs are rejected');
select throws_ok($$select internal.read_own_assessment_submissions(array[null::uuid])$$,'22023',null,'Null input IDs are rejected');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000013',true);
select is(internal.read_own_assessment_submissions(array['99990000-0000-4000-8000-000000000001'::uuid]),'[]'::jsonb,'Peer receives no other learner raw source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select throws_ok($$select internal.read_own_assessment_submissions(array['99990000-0000-4000-8000-000000000001'::uuid])$$,'42501',null,'Staff cannot call learner-own source reader');
select internal.return_learning_submission('99991000-0000-4000-8000-000000000001','Explain checking.',1);
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select throws_ok($$select internal.read_own_assessment_submissions(array['99990000-0000-4000-8000-000000000001'::uuid])$$,'42501',null,'Parent cannot call raw learner-own source reader');
reset role;update app.assessments set assignment_state='CLOSED'where school_id='10000000-0000-4000-8000-000000000001'and id='99990000-0000-4000-8000-000000000001';set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is(internal.read_own_assessment_submissions(array['99990000-0000-4000-8000-000000000001'::uuid])->0->>'status','RETURNED','Closed availability retains current returned own history');
select is(internal.read_own_assessment_submissions(array['99990000-0000-4000-8000-000000000001'::uuid])->0->>'returnFeedback','Explain checking.','Current teacher return feedback follows the exact source');
reset role;update app.enrollments set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and class_id='30000000-0000-4000-8000-000000000001'and student_actor_id='20000000-0000-4000-8000-000000000012';set local role cuevo_api;
select throws_ok($$select internal.read_own_assessment_submissions(array['99990000-0000-4000-8000-000000000001'::uuid])$$,'42501',null,'Revoked enrollment denies exact historical source');
reset role;
select ok(not has_function_privilege('anon','internal.read_own_assessment_submissions(uuid[])','EXECUTE'),'Anonymous role has no private reader grant');
select ok(not has_function_privilege('authenticated','internal.read_own_assessment_submissions(uuid[])','EXECUTE'),'Browser role has no private reader grant');
select ok(not has_function_privilege('service_role','internal.read_own_assessment_submissions(uuid[])','EXECUTE'),'Service role has no private reader grant');
select ok(not has_function_privilege('cuevo_worker','internal.read_own_assessment_submissions(uuid[])','EXECUTE'),'Worker role has no private reader grant');
select ok(has_function_privilege('cuevo_api','internal.read_own_assessment_submissions(uuid[])','EXECUTE'),'Only the API owns the protected reader');
select*from finish();rollback;
